export const saveUser = async (user: User): Promise<User> => {
    // Prepare payload. If password changes, encrypt it.
    const payload: any = {
        name: user.name,
        email: user.email,
        role: user.role,
        avatar: user.avatar,
        active: user.active
    };

    // Only update password if provided (for edits) or required (for new)
    if (user.password) {
        payload.password = mockEncrypt(user.password);
    }

    if (user.id && user.id.length > 10) { // Simple check if UUID-ish
        // Update
        const { data, error } = await supabase
            .from('users')
            .update(payload)
            .eq('id', user.id)
            .select()
            .single();
        if (error) throw error;
        return { ...user, ...data };
    } else {
        // Insert
        const { data, error } = await supabase
            .from('users')
            .insert([payload])
            .select()
            .single();
        if (error) throw error;
        return { ...user, id: data.id };
    }
};

