                  <QuickAction title="Gestión de Tareas" desc="Ver o crear nuevas labores" icon={ClipboardList} path="/activities" color="bg-indigo-600" />
                  <QuickAction title="Consultar Asistencia" desc="Historial de marcas de personal" icon={Search} path="/attendance/search" color="bg-emerald-600" />
              </div>

