                                    </div>
                                    <p className="text-lg font-bold text-slate-800 capitalize leading-none mb-1">{currentWeatherData.condition}</p>
                                    <p className="text-slate-400 text-xs font-bold uppercase tracking-wider">Colbún, VII Región</p>
