const getWeatherInfo = (code: number) => {
    if (code === 0) return { label: 'Despejado', icon: Sun };
    if (code === 1 || code === 2 || code === 3) return { label: 'Parcial', icon: CloudSun };
    if (code >= 45 && code <= 48) return { label: 'Niebla', icon: Cloud };
    if (code >= 51 && code <= 55) return { label: 'Llovizna', icon: CloudDrizzle };
    if (code >= 61 && code <= 67) return { label: 'Lluvia', icon: CloudRain };
    if (code >= 80 && code <= 82) return { label: 'Chubascos', icon: CloudRain };
    if (code >= 95) return { label: 'Tormenta', icon: CloudRain };
    return { label: 'Nublado', icon: Cloud };
};

type WeatherMetric = 'temp' | 'precip' | 'wind';

const Dashboard: React.FC = () => {
  // Use navigate hook inside the Dashboard component
  const navigate = useNavigate();
  const [stats, setStats] = useState({ workers: 0, pending: 0, inProgress: 0, completed: 0 });
  const [loadingStats, setLoadingStats] = useState(true);
  const [selectedDayIndex, setSelectedDayIndex] = useState(0);
  const [activeMetric, setActiveMetric] = useState<WeatherMetric>('temp');
  const [weatherData, setWeatherData] = useState<any[]>([]);
  const [loadingWeather, setLoadingWeather] = useState(true);

  const LAT = -35.6789825;
  const LON = -71.4169345;

  useEffect(() => {
    const loadData = async () => {
        try {
            setLoadingStats(true);
            const kpis = await getDashboardStats();
            setStats(kpis);
        } catch (error) {
            console.error(error);
        } finally {
            setLoadingStats(false);
        }
    };
    loadData();

    const fetchWeather = async () => {
        try {
            setLoadingWeather(true);
            const response = await fetch(
                `https://api.open-meteo.com/v1/forecast?latitude=${LAT}&longitude=${LON}&current=temperature_2m,relative_humidity_2m,weather_code,wind_speed_10m,precipitation&hourly=temperature_2m,precipitation_probability,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto`
            );
            const data = await response.json();
            const mappedData = data.daily.time.map((dateStr: string, index: number) => {
                const dateObj = new Date(dateStr + 'T00:00:00');
                const weatherInfo = getWeatherInfo(data.daily.weather_code[index]);
                let hourlyIndices: number[] = [];
                if (index === 0) {
                    const currentHour = new Date().getHours();
                    for (let i = 0; i < 8; i++) hourlyIndices.push(currentHour + (i * 3));
                } else {
                    const startDayIdx = index * 24;
                    [0, 3, 6, 9, 12, 15, 18, 21].forEach(h => hourlyIndices.push(startDayIdx + h));
                }
                const hourly = hourlyIndices.map(globalIdx => {
                    if (globalIdx >= data.hourly.time.length) return null;
                    const timeObj = new Date(data.hourly.time[globalIdx]);
                    return {
                        time: timeObj.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
                        temp: Math.round(data.hourly.temperature_2m[globalIdx]),
                        precip: data.hourly.precipitation_probability[globalIdx],
                        wind: Math.round(data.hourly.wind_speed_10m[globalIdx])
                    };
                }).filter(Boolean);

                return {
                    id: index,
                    day: (index === 0 ? 'Hoy' : dateObj.toLocaleDateString('es-ES', { weekday: 'short' })).toUpperCase(),
                    fullDay: dateObj.toLocaleDateString('es-ES', { weekday: 'long' }),
                    max: Math.round(data.daily.temperature_2m_max[index]),
                    min: Math.round(data.daily.temperature_2m_min[index]),
                    current: index === 0 ? Math.round(data.current.temperature_2m) : Math.round(data.daily.temperature_2m_max[index]),
                    condition: weatherInfo.label,
                    icon: weatherInfo.icon,
                    hourly,
                    humidity: index === 0 ? data.current.relative_humidity_2m : 50, 
                    wind: index === 0 ? Math.round(data.current.wind_speed_10m) : Math.round(data.daily.wind_speed_10m_max?.[index] || 15),
                    rainProb: data.daily.precipitation_probability_max[index]
                };
            });
            setWeatherData(mappedData);
        } catch (error) { console.error(error); } finally { setLoadingWeather(false); }
    };
    fetchWeather();
  }, []);

  const currentWeatherData = weatherData[selectedDayIndex] || { current: 0, condition: '...', fullDay: '...', rainProb: 0, humidity: 0, wind: 0, hourly: [], icon: Sun };
  const getChartConfig = () => {
      switch(activeMetric) {
          case 'precip': return { dataKey: 'precip', color: '#3b82f6', fillId: 'colorPrecip', unit: '%' };
          case 'wind': return { dataKey: 'wind', color: '#10b981', fillId: 'colorWind', unit: ' km/h' };
          default: return { dataKey: 'temp', color: '#f59e0b', fillId: 'colorTemp', unit: '°' };
      }
  };
  const chartConfig = getChartConfig();

  const renderValue = (val: number) => loadingStats ? <div className="animate-pulse bg-slate-200 h-8 w-12 rounded"></div> : val.toString();

  return (
    <div className="space-y-8 pb-12">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <div className="flex items-center gap-2 text-blue-600 mb-1">
            <Zap size={16} className="fill-blue-600" />
            <span className="text-xs font-bold uppercase tracking-widest">Resumen Operativo</span>
          </div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Agro Comice <span className="text-blue-600">Ltda</span></h1>
          <p className="text-slate-500 mt-1 font-medium">Control centralizado de labores agrícolas y servicios.</p>
        </div>
        <div className="bg-white px-4 py-2 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
           <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
           <span className="text-xs font-bold text-slate-600">SISTEMA EN LÍNEA</span>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Trabajadores Activos" value={renderValue(stats.workers)} icon={Users} color="bg-blue-600" subtitle="En Campo" />
        <StatCard title="Tareas Pendientes" value={renderValue(stats.pending)} icon={Clock} color="bg-orange-500" subtitle="Urgente" />
        <StatCard title="En Progreso" value={renderValue(stats.inProgress)} icon={TrendingUp} color="bg-indigo-600" subtitle="Hoy" />
        <StatCard title="Completadas" value={renderValue(stats.completed)} icon={CheckCircle2} color="bg-emerald-600" subtitle="Mes Actual" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          <div className="lg:col-span-4 space-y-6">
              <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest px-1">Accesos Directos</h3>
              <div className="grid grid-cols-1 gap-4">
                  <QuickAction title="Reportar Medidores" desc="Registrar agua, luz o gas" icon={Gauge} path="/meter-readings" color="bg-blue-600" />
                  <QuickAction title="Gestión de Tareas" desc="Ver o crear nuevas labores" icon={ClipboardList} path="/activities" color="bg-indigo-600" />
                  <QuickAction title="Consultar Asistencia" desc="Historial de marcas de personal" icon={Search} path="/attendance/search" color="bg-emerald-600" />
              </div>

              <div className="bg-gradient-to-br from-blue-600 to-blue-800 rounded-3xl p-6 text-white shadow-lg relative overflow-hidden group">
                  <Sparkles className="absolute -right-4 -bottom-4 w-32 h-32 text-white/10 group-hover:scale-125 transition-transform duration-700" />
                  <h4 className="text-xl font-bold mb-2">IA Studio</h4>
                  <p className="text-blue-100 text-sm mb-4">Usa inteligencia artificial para análisis de cultivos y clima.</p>
                  <button onClick={() => navigate('/ai-tools')} className="bg-white text-blue-700 px-4 py-2 rounded-xl text-sm font-bold hover:bg-blue-50 transition-colors">Abrir Herramientas</button>
              </div>
          </div>

          <div className="lg:col-span-8 space-y-6">
              <div className="bg-white p-6 md:p-8 rounded-3xl shadow-sm border border-slate-100 min-h-[500px] flex flex-col relative overflow-hidden">
                {loadingWeather ? (
                    <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
                        <Loader2 size={48} className="animate-spin mb-4 text-blue-500"/>
                        <p className="font-medium">Sincronizando meteorología...</p>
                    </div>
                ) : (
                    <>
                        <div className="flex flex-col md:flex-row justify-between items-start gap-6 mb-8">
                            <div className="flex gap-6">
                                <div className="p-4 bg-slate-50 rounded-3xl border border-slate-100">
                                    <currentWeatherData.icon size={64} className="text-amber-400 drop-shadow-sm" />
                                </div>
                                <div>
                                    <div className="flex items-baseline gap-2">
                                        <h2 className="text-7xl font-black text-slate-900 tracking-tighter">{currentWeatherData.current}°</h2>
                                    </div>
                                    <p className="text-lg font-bold text-slate-800 capitalize leading-none mb-1">{currentWeatherData.condition}</p>
                                    <p className="text-slate-400 text-xs font-bold uppercase tracking-wider">Colbún, VII Región</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-3 md:grid-cols-1 gap-4 md:gap-2 w-full md:w-auto">
                                <div className="bg-blue-50/50 p-2 md:p-0 md:bg-transparent rounded-xl text-center md:text-right">
                                    <p className="text-[10px] font-bold text-blue-600 uppercase">Lluvia</p>
                                    <p className="text-lg font-black text-slate-800">{currentWeatherData.rainProb}%</p>
                                </div>
                                <div className="bg-emerald-50/50 p-2 md:p-0 md:bg-transparent rounded-xl text-center md:text-right">
                                    <p className="text-[10px] font-bold text-emerald-600 uppercase">Humedad</p>
                                    <p className="text-lg font-black text-slate-800">{currentWeatherData.humidity}%</p>
                                </div>
                                <div className="bg-orange-50/50 p-2 md:p-0 md:bg-transparent rounded-xl text-center md:text-right">
                                    <p className="text-[10px] font-bold text-orange-600 uppercase">Viento</p>
                                    <p className="text-lg font-black text-slate-800">{currentWeatherData.wind}<span className="text-xs ml-0.5">km/h</span></p>
                                </div>
                            </div>
                        </div>

                        <div className="flex gap-2 mb-6 bg-slate-50 p-1 rounded-2xl w-fit">
                            {['temp', 'precip', 'wind'].map((m) => (
                                <button 
                                    key={m}
                                    onClick={() => setActiveMetric(m as WeatherMetric)}
                                    className={`px-4 py-2 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${activeMetric === m ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                                >
                                    {m === 'temp' ? 'Temperatura' : m === 'precip' ? 'Lluvia' : 'Viento'}
                                </button>
                            ))}
                        </div>

                        <div className="w-full h-44 min-w-0 relative">
                            <ResponsiveContainer width="99.9%" height="100%">
                                <AreaChart data={currentWeatherData.hourly}>
                                    <defs>
                                        <linearGradient id={chartConfig.fillId} x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor={chartConfig.color} stopOpacity={0.2}/>
                                            <stop offset="95%" stopColor={chartConfig.color} stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 'bold', fill: '#94a3b8'}} />
                                    <YAxis hide domain={['auto', 'auto']} />
