                                        contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold'}}
                                    />
                                    <Area 
                                        type="monotone" 
                                        dataKey={chartConfig.dataKey} 
                                        stroke={chartConfig.color} 
                                        strokeWidth={3} 
                                        fillOpacity={1} 
                                        fill={`url(#${chartConfig.fillId})`} 
                                        animationDuration={1000}
                                    >
                                        <LabelList dataKey={chartConfig.dataKey} position="top" offset={10} content={(props: any) => (
                                            <text x={props.x} y={props.y} dy={-10} fill={chartConfig.color} fontSize={10} fontWeight="900" textAnchor="middle">
                                                {props.value}{chartConfig.unit}
                                            </text>
                                        )} />
                                    </Area>
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>

                        <div className="mt-auto pt-6 border-t border-slate-100 overflow-x-auto">
                            <div className="flex gap-3 pb-2 min-w-max">
                                {weatherData.map((day, idx) => (
                                    <button 
