        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 bg-slate-50">

            {/* CHAT TAB */}
            {activeTab === 'chat' && (
                <div className="flex flex-col h-full max-w-4xl mx-auto">
