        <StatCard title="Completadas" value={renderValue(stats.completed)} icon={CheckCircle2} color="bg-emerald-600" subtitle="Mes Actual" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

