                              <defs>
                                  <linearGradient id={chartConfig.fillId} x1="0" y1="0" x2="0" y2="1">
                                      <stop offset="5%" stopColor={chartConfig.color} stopOpacity={0.2}/>
                                      <stop offset="95%" stopColor={chartConfig.color} stopOpacity={0}/>
